script:
// Client Script for Quotation doctype with 700ms debouncing
// Add this as a Client Script in Frappe with DocType: "Quotation"

// Global variable to store debounce timers for each field
window.search_timers = window.search_timers || {};

frappe.ui.form.on('Quotation', {
    refresh: function(frm) {
        applyCustomItemSearch(frm);
    }
});

function applyCustomItemSearch(frm) {
    if (frm.fields_dict['items'] && frm.fields_dict['items'].grid) {
        // Get the item_code field
        const item_code_field = frm.fields_dict['items'].grid.get_field('item_code');

        // Override the default get_query with our debounced version
        item_code_field.get_query = function(doc, cdt, cdn) {
            return {
                query: "erpnext_enhancements.api.item_search.debounced_item_search",
                filters: {}
            };
        };

        // Override the setup_awesomeplete method to add debouncing
        const original_setup = item_code_field.setup_awesomeplete;
        item_code_field.setup_awesomeplete = function() {
            // Call original setup first
            if (original_setup) {
                original_setup.call(this);
            }

            // Now add our custom debounced behavior
            if (this.$input && this.awesomplete) {
                setupDebouncedSearch(this, doc, cdt, cdn);
            }
        };
    }
}

function setupDebouncedSearch(field, doc, cdt, cdn) {
    const $input = field.$input;
    const awesomplete = field.awesomplete;

    // Create unique timer key for this field instance
    const timer_key = `${cdt}_${cdn}_${field.df.fieldname}`;

    // Store original input handler
    const original_input_handler = awesomplete._input;

    // Override the input handler with debounced version
    $input.off('input.awesomplete');

    $input.on('input.awesomplete', function(e) {
        const search_term = this.value;

        // Clear existing timer for this field
        if (window.search_timers[timer_key]) {
            clearTimeout(window.search_timers[timer_key]);
        }

        // If search term is empty, clear results immediately
        if (!search_term || search_term.length < 2) {
            awesomplete.list = [];
            awesomplete.close();
            return;
        }

        // Set new timer with 700ms delay
        window.search_timers[timer_key] = setTimeout(() => {
            // Perform the actual search
            performDebouncedSearch(field, search_term, doc, cdt, cdn);

            // Clean up timer
            delete window.search_timers[timer_key];
        }, 700);
    });

    // Handle focus event (immediate search for focus)
    $input.off('focus.custom_search');
    $input.on('focus.custom_search', function() {
        if (this.value && this.value.length >= 2) {
            // Clear any pending timer
            if (window.search_timers[timer_key]) {
                clearTimeout(window.search_timers[timer_key]);
            }
            // Immediate search on focus
            performDebouncedSearch(field, this.value, doc, cdt, cdn);
        }
    });
}

function performDebouncedSearch(field, search_term, doc, cdt, cdn) {
    // Get the query configuration
    const query_config = field.get_query(doc, cdt, cdn);

    // Perform the search
    frappe.call({
        method: query_config.query,
        args: {
            doctype: 'Item',
            txt: search_term,
            searchfield: 'name',
            start: 0,
            page_len: 20,
            filters: query_config.filters || {}
        },
        callback: function(response) {
            if (response.message) {
                // Format results for awesomplete - now including custom_sku_code
                const results = response.message.map(item => {
                    // item[0] = item_code, item[1] = item_name, item[2] = custom_sku_code
                    const item_code = item[0];
                    const item_name = item[1];
                    const custom_sku_code = item[2];

                    // Create display label with all three fields
                    let label_parts = [item_code];

                    if (custom_sku_code && custom_sku_code.trim()) {
                        label_parts.push(`SKU: ${custom_sku_code}`);
                    }

                    if (item_name) {
                        label_parts.push(item_name);
                    }

                    return {
                        label: label_parts.join(' - '),
                        value: item_code
                    };
                });

                // Update awesomplete list
                field.awesomplete.list = results;

                // Open dropdown if we have results
                if (results.length > 0) {
                    field.awesomplete.open();
                }
            }
        }
    });
}

// Apply to existing rows as well
frappe.ui.form.on('Quotation Item', {
    form_render: function(frm, cdt, cdn) {
        applyCustomItemSearch(frm);
    }
});

frappe.ui.form.on('Sales Order', {
    onload: function(frm) {
        if (frm.doc.docstatus !== 1) {
            toggle_custom_room_field(frm);
        }
    },

    custom_rooms_assign: function(frm) {
        if (frm.doc.docstatus === 1) return;

        frm.fields_dict["items"].grid.grid_rows.forEach(row => {
            let item = row.doc;
            if (!item.custom_room) {
                frappe.model.set_value(item.doctype, item.name, 'custom_room', frm.doc.custom_rooms_assign);
            }
        });
    },

    custom_room: function(frm) {
        filter_items_by_room(frm);
        if (frm.doc.docstatus !== 1) {
            calculate_total(frm);
        }
    },

    validate: function(frm) {
        if (frm.doc.docstatus !== 1) {
            toggle_custom_room_field(frm);
            calculate_total(frm);
        }
    }
});

frappe.ui.form.on('Sales Order Item', {
    items_add: function(frm, cdt, cdn) {
        if (frm.doc.docstatus === 1) return;

        let row = locals[cdt][cdn];

        if (frm.doc.custom_rooms_assign) {
            frappe.model.set_value(cdt, cdn, 'custom_room', frm.doc.custom_rooms_assign);
        }

        setTimeout(() => {
            toggle_custom_room_field(frm);
            calculate_total(frm);
        }, 200);
    },

    items_remove: function(frm) {
        if (frm.doc.docstatus !== 1) {
            toggle_custom_room_field(frm);
            calculate_total(frm);
        }
    },

    item_code: function(frm, cdt, cdn) {
        if (frm.doc.docstatus !== 1) {
            frappe.after_ajax(() => {
                toggle_custom_room_field(frm);
                calculate_total(frm);
            });
        }
    },

    qty: function(frm, cdt, cdn) {
        if (frm.doc.docstatus !== 1) {
            frappe.after_ajax(() => calculate_total(frm));
        }
    },

    amount: function(frm, cdt, cdn) {
        if (frm.doc.docstatus !== 1) {
            frappe.after_ajax(() => calculate_total(frm));
        }
    }
});

// ✅ Show/Hide "custom_room" Based on Multiple Rooms
function toggle_custom_room_field(frm) {
    if (frm.doc.docstatus === 1) return;

    let rooms = new Set();

    frm.doc.items.forEach(item => {
        if (item.custom_room) {
            rooms.add(item.custom_room);
        }
    });

    frm.set_df_property("custom_room", "hidden", rooms.size <= 1);

    if (rooms.size <= 1) {
        frm.set_value("custom_room", "");
    }
}

// ✅ Filter Items Based on Selected Room
function filter_items_by_room(frm) {
    frm.fields_dict["items"].grid.grid_rows.forEach(row => {
        $(row.row).toggle(!frm.doc.custom_room || row.doc.custom_room === frm.doc.custom_room);
    });
}

// ✅ Calculate Total Room Amount & Qty (With UOM)
function calculate_total(frm) {
    if (frm.doc.docstatus === 1) return;

    let total = 0, room_qty = 0, room_uom = "";

    frm.doc.items.forEach(item => {
        if (!frm.doc.custom_room || item.custom_room === frm.doc.custom_room) {
            total += flt(item.amount);
            room_qty += flt(item.qty);

            if (!room_uom && item.uom) {
                room_uom = item.uom;
            }
        }
    });

    let room_qty_with_uom = room_qty ? `${room_qty} ${room_uom || ''}`.trim() : '';

    frm.set_value('custom_total_room_inr', total);
    frm.set_value('custom_room_qty', room_qty_with_uom);
    frm.refresh_fields(['custom_total_room_inr', 'custom_room_qty']);
}

var itemCodeUOMs = {};

frappe.ui.form.on("Sales Order Item", {
    item_code: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.item_code) return;

        if (itemCodeUOMs[row.item_code]) {
            setUOMValues(row, cdt, cdn, itemCodeUOMs[row.item_code]);
        } else {
            frappe.call({
                method: "erpnext_mxt.custom_functions.quotation.get_uoms",
                args: { item_code: row.item_code },
                callback: function(response) {
                    if (response.message) {
                        itemCodeUOMs[row.item_code] = response.message;
                        setUOMValues(row, cdt, cdn, response.message);
                    }
                }
            });
        }
    },
    qty: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.item_code) return;

        if (itemCodeUOMs[row.item_code]) {
            setUOMValues(row, cdt, cdn, itemCodeUOMs[row.item_code]);
        } else {
            frappe.call({
                method: "erpnext_mxt.custom_functions.quotation.get_uoms",
                args: { item_code: row.item_code },
                callback: function(response) {
                    if (response.message) {
                        itemCodeUOMs[row.item_code] = response.message;
                        setUOMValues(row, cdt, cdn, response.message);
                    }
                }
            });
        }
    },
});

function setUOMValues(row, cdt, cdn, uoms) {
    let pcs_factor = 1, box_factor = 1, sqft_factor = 1;

    uoms.forEach((factor) => {
        if (factor.uom.toLowerCase() === "nos") pcs_factor = factor.conversion_factor;
        if (factor.uom.toLowerCase() === "box") box_factor = factor.conversion_factor;
        if (factor.uom.toLowerCase() === "square foot") sqft_factor = factor.conversion_factor;
        if (factor.uom.toLowerCase() === "sqft") sqft_factor = factor.conversion_factor;
    });

    if (!row.qty) {
        frappe.model.set_value(cdt, cdn, "custom_pcs", pcs_factor.toFixed(2));
        frappe.model.set_value(cdt, cdn, "custom_box", box_factor.toFixed(2));
        frappe.model.set_value(cdt, cdn, "custom_sqft", sqft_factor.toFixed(2));
    } else {
        frappe.model.set_value(cdt, cdn, "custom_pcs", (row.qty * pcs_factor).toFixed(2));
        frappe.model.set_value(cdt, cdn, "custom_box", (row.qty * box_factor).toFixed(2));
        frappe.model.set_value(cdt, cdn, "custom_sqft", (row.qty * sqft_factor).toFixed(2));
    }
}

var brandDiscounts = {};
var isBrandDiscountTriggered = false;

frappe.ui.form.on("Sales Order", {
    refresh: function(frm) {
        // Add a button in the form header
        frm.add_custom_button(__('Update Brand Discounts'), function() {
            frm.trigger("update_brand_discounts");
            setApplyDiscount(frm);
        }).addClass('btn-primary'); // Make it visually distinct
    },
    before_save: function(frm) {
        update_brand_discounts_sync(frm);
        setApplyDiscount(frm);
    },
    onload: function(frm) {
        if (!isBrandDiscountTriggered) {
            // Fetch all pricing rules and store discount percentages
            frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Pricing Rule",
                        fields: ["name", "discount_percentage"],
                        limit_page_length: 1000
                    },
                    async: false,  // 🔥 Make it synchronous for guaranteed availability in before_save
                    callback: function(response) {
                        if (response.message) {
                            response.message.forEach(rule => {
                                getBrandFromPricingRule(rule.name, rule.discount_percentage, brandDiscounts);
                            });
                        }
                    }
                });
        }
    },
    validate: function(frm) {

        // let brandDiscounts = {}; // Store max discount per brand
        let exceeds_discount = false;

        // Check manual discounts in the custom discount table
        (frm.doc.custom_dicount_table || []).forEach(row => {
            let brand = row.brand;
            let manual_discount = row.manual_discount || 0;

            if (brand && brandDiscounts[brand] !== undefined) {
                if (manual_discount > brandDiscounts[brand]) {
                    exceeds_discount = true;
                }
            }
        });

        if (exceeds_discount) {
            if ("custom_requires_approval_for_discount" in frm.doc) {
                frm.set_value("custom_requires_approval_for_discount", 1);
            } else {
                console.error("Error: Field 'custom_requires_approval' not found in Sales Order Doctype!");
            }

            // Move to "Pending Approval" if required
            if (frm.doc.custom_requires_approval_for_discount) {
                //frappe.msgprint(("🔄 Sales Order requires approval. Moving to 'Pending Approval'."));
                frm.refresh(); // Refresh the form to apply changes
            } else {
               // frappe.msgprint(("⚠ Manual Discount exceeded, but approval is not required."));
            }
        }
    }
});

// Fetch brand separately for each Pricing Rule
function getBrandFromPricingRule(pricingRuleName, discountPercentage, brandDiscounts) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Pricing Rule",
            name: pricingRuleName
        },
        async: true,
        callback: function(response) {
            //console.log("get response", response.message)
            if (response.message && response.message.brands) {
                // Store discount percentage for the brand
                brandDiscounts[response.message.brands[0].brand] = discountPercentage || 0;
                
            }

        }
    });
}

function update_brand_discounts_sync(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) return;

    const brand_totals = {};
    const manual_discounts = {};

    // Get manual discounts
    (frm.doc.custom_dicount_table || []).forEach(row => {
        manual_discounts[row.brand] = row.manual_discount || 0;
    });

    // Compute brand totals
    (frm.doc.items || []).forEach(item => {
        if (!item.brand) return;

        if (!brand_totals[item.brand]) {
            brand_totals[item.brand] = {
                value: 0,
                discount_percentage: 0,
                manual_discount: manual_discounts[item.brand] || 0
            };
        }

        brand_totals[item.brand].value += (item.price_list_rate * item.qty);
    });

    // Assume brandDiscounts is preloaded with { brand: discount_percentage } format
    frm.clear_table("custom_dicount_table");
    Object.keys(brand_totals).forEach(brand => {
        const brandData = brand_totals[brand];
        const max_discount = brandDiscounts[brand] || 0;
        const applied_discount = brandData.manual_discount > 0 ? brandData.manual_discount : max_discount;
        const discount_amount = (brandData.value * applied_discount) / 100;
        const total_value = brandData.value - discount_amount;

        let row = frm.add_child("custom_dicount_table", {
            brand: brand,
            value: brandData.value.toFixed(2),
            max_discount: max_discount,
            disc_: applied_discount,
            manual_discount: brandData.manual_discount,
            discount_amount: discount_amount.toFixed(2),
            total_value: total_value.toFixed(2)
        });
    });

    // IMPORTANT: Update the items' discount percentages
    (frm.doc.items || []).forEach(row => {
        const discount_row = frm.doc.custom_dicount_table.find(d => d.brand === row.brand);
        if (discount_row) {
            const discount_value = discount_row.manual_discount > 0 ? discount_row.manual_discount : discount_row.disc_;
            row.discount_percentage = discount_value;
        }
    });

    frm.refresh_field("custom_dicount_table");
    frm.refresh_field("items");
}


// Function to apply manual discounts
function apply_brand_discounts(frm) {
    let brand_discounts = {};
    let exceeds_discount = false;

    // Collect discounts from the "Brand Discount Details" child table
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && row.manual_discount !== undefined) {
            if (row.manual_discount != 0)
            {
            brand_discounts[row.brand] = row.manual_discount;
            }
            else
            {
                brand_discounts[row.brand] = row.disc_;
            }
        }
        if (row.manual_discount > row.max_discount) {
            exceeds_discount = true;
        }
    });

    let items_updated = false;

    // Ensure new items also get checked
    (frm.doc.items || []).forEach(item => {
        if (item.brand && brand_discounts[item.brand] !== undefined) {
            let new_discount = brand_discounts[item.brand];

            // Update discount percentage
            frappe.model.set_value(item.doctype, item.name, "discount_percentage", new_discount);
            items_updated = true;
        }
    });

    // Recalculate custom discount table values
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && brand_discounts[row.brand] !== undefined) {
            row.discount_amount = (row.value * (row.manual_discount / 100)).toFixed(2);
            row.total_value = (row.value - row.discount_amount).toFixed(2);
        }
    });

    // Refresh both tables after modification
    frm.refresh_field("items");
    frm.refresh_field("custom_dicount_table");

    if (exceeds_discount) {

        // Ensure the field exists before setting its value
        if ("custom_requires_approval_for_discount" in frm.doc) {
            frm.set_value("custom_requires_approval_for_discount", 1);
        } else {
            console.error("Error: Field 'custom_requires_approval' not found in Sales Order Doctype!");
        }

        // Move to "Pending Approval" if required
        if (frm.doc.custom_requires_approval_for_discount) {
           // frappe.msgprint(("🔄 Sales Order requires approval. Moving to 'Pending Approval'."));
            frm.refresh(); // Refresh the form to apply changes
        } else {
          //  frappe.msgprint(("⚠ Manual Discount exceeded, but approval is not required."));
        }
    }
}

// Auto apply discounts when manual discount changes
frappe.ui.form.on('Brand Discount Details', {
    manual_discount: function(frm) {
        apply_brand_discounts(frm);
    },
});

frappe.ui.form.on("Sales Order", {
    update_brand_discounts: function(frm) {
    console.log("1");

    if (!frm.doc.items || frm.doc.items.length === 0) {
        frm.clear_table("custom_dicount_table");
        frm.refresh_field("custom_dicount_table");
        console.log("2");
        return;
    }

    let brand_totals = {};
    let manual_discounts = {};

    // Store existing manual discounts
    if (frm.doc.custom_dicount_table) {
        frm.doc.custom_dicount_table.forEach(row => {
            manual_discounts[row.brand] = row.manual_discount || 0;
        });
    }

    // Calculate brand totals
    frm.doc.items.forEach(item => {
        if (item.brand) {
            if (!brand_totals[item.brand]) {
                brand_totals[item.brand] = {
                    value: 0,
                    discount_percentage: 0,
                    discount_amount: 0,
                    manual_discount: manual_discounts[item.brand] || 0 // Preserve manual discount
                };
            }
            brand_totals[item.brand].value += (item.price_list_rate * item.qty);
        }
    });

    console.log(brand_totals);

    frappe.call({
        method: "erpnext_mxt.custom_functions.brand_discount.get_brand_discounts",
        args: {
            brand_list: Object.keys(brand_totals)
        },
        callback: function(r) {
            if (r.message && Array.isArray(r.message) && r.message.length > 0) {
                frm.clear_table("custom_dicount_table");
                console.log("3");

                r.message.forEach(rule => {
                    if (brand_totals[rule.brand]) {
                        brand_totals[rule.brand].max_discount_percentage = rule.discount_percentage || 0;
                        brand_totals[rule.brand].discount_percentage = rule.custom_default_discount_percentage || 0;

                        // If manual discount exists, override discount_percentage
                        if (brand_totals[rule.brand].manual_discount > 0) {
                            brand_totals[rule.brand].discount_percentage = brand_totals[rule.brand].manual_discount;
                        }

                        brand_totals[rule.brand].discount_amount =
                            (brand_totals[rule.brand].value * brand_totals[rule.brand].discount_percentage) / 100;
                    }
                });

                Object.keys(brand_totals).forEach(brand => {
                    let row = frm.add_child("custom_dicount_table");
                    console.log("8");
                    if (row) {
                        row.brand = brand;
                        row.value = brand_totals[brand].value.toFixed(2);
                        row.disc_ = brand_totals[brand].discount_percentage;
                        row.discount_amount = brand_totals[brand].discount_amount.toFixed(2);
                        row.total_value = (brand_totals[brand].value - brand_totals[brand].discount_amount).toFixed(2);
                        row.max_discount = brand_totals[brand].max_discount_percentage;
                        row.manual_discount = brand_totals[brand].manual_discount || 0; // Restore manual discount
                        console.log(row);
                    }
                });

                frm.refresh_field("custom_dicount_table");
                console.log("Table Refreshed");
            } else {
                console.log("Refresh");
                frm.clear_table("custom_dicount_table");
                frm.refresh_field("custom_dicount_table");
            }

            // Apply discount to items based on updated discount table
            frm.doc.items.forEach(row => {
                console.log("9");
                frappe.db.get_value('Item', row.item_code, 'brand', (r) => {
                    if (r && r.brand) {
                        let brand = r.brand;
                        let discount_row = frm.doc.custom_dicount_table.find(d => d.brand === brand);

                        // Use manual discount if set, otherwise use fetched discount
                        let discount_value = discount_row ? 
                            (discount_row.manual_discount > 0 ? discount_row.manual_discount : discount_row.disc_) 
                            : 0;

                        frappe.model.set_value(row.doctype, row.name, 'discount_percentage', discount_value);

                        setTimeout(() => {
                            frappe.model.set_value(row.doctype, row.name, 'discount_percentage', discount_value);
                        }, 500);
                    }
                });
            });
        }
    });

    frm.refresh();
}


});

// Function to get brand from Pricing Rule
function setApproval(frm) {
    let requiresApproval = false;
    let brandDiscounts = {};
    console.log("4")

    // Collect unique brands from the items in the form
    let brandList = [...new Set((frm.doc.items || []).map(item => item.brand).filter(brand => brand))];

    if (brandList.length === 0) {
        frm.set_value("custom_requires_approval_for_discount", 0);
        return;
    }

    // Call the server-side function to get brand discounts
    frappe.call({
        method: "erpnext_mxt.custom_functions.brand_discount.get_brand_discounts",
        args: {
            brand_list: brandList // Pass as an array instead of JSON.stringify
        },
        async: false, // Synchronous execution (consider avoiding this in production)
        callback: function(response) {
            if (response.message) {
                console.log("5")
                // Map brand discounts
                response.message.forEach(discount => {
                    if (discount.brand) {
                        brandDiscounts[discount.brand] = discount.discount_percentage || 0;
                    }
                    if (discount.custom_default_discount_percentage) {
                        brandDiscounts[discount.min_brand] = discount.custom_default_discount_percentage || 0;
                    }
                });
                

                // Iterate over items and check discount limits
                (frm.doc.items || []).forEach(item => {
                    if (item.item_code && item.brand) {
                        let itemDiscount = item.discount_percentage || 0;
                        let maxAllowedDiscount = brandDiscounts[item.brand] || 0;
                        let minAllowedDiscount = brandDiscounts[item.min_brand] || 0;

                        if (itemDiscount > maxAllowedDiscount || itemDiscount < minAllowedDiscount) {
                            requiresApproval = true;
                            // frappe.show_alert({
                            //     message: Item ${item.item_code} needs discount approval,
