// Fetch brand separately for each Pricing Rule
function setApplyDiscount(frm) {

    let brandDiscountMap = {};

    // Iterate over items to compute the average discount per brand
    (frm.doc.items || []).forEach(row => {
        if (!brandDiscountMap[row.brand]) {
            brandDiscountMap[row.brand] = {
                total_discount: 0,
                count: 0
            };
        }
        brandDiscountMap[row.brand].total_discount += row.discount_percentage || 0;
        brandDiscountMap[row.brand].count += 1;
    });

    // Compute the average discount for each brand
    Object.keys(brandDiscountMap).forEach(brand => {
        brandDiscountMap[brand].average_discount =
            brandDiscountMap[brand].count > 0 ?
            (brandDiscountMap[brand].total_discount / brandDiscountMap[brand].count) :
            0;
    });

    // Update the custom_discount_table with the computed average discounts
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (brandDiscountMap[row.brand]) {
            row.applied_discount = brandDiscountMap[row.brand].average_discount;
        }
    });

    // Refresh the field to reflect changes in the UI
    frm.refresh_field('custom_dicount_table');
    frm.refresh();
}

