// Function to generate and download CSV
function download_csv(frm, selected_columns) {
    let data = frm.doc.items.map(item => {
        let row = {};
        selected_columns.forEach(col => {
            row[col] = item[col] || ''; // Handle missing values
        });
        return row;
    });

    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += selected_columns.join(",") + "\n"; // CSV Headers
    data.forEach(row => {
        csvContent += selected_columns.map(col => row[col]).join(",") + "\n";
    });

    let encodedUri = encodeURI(csvContent);
    let link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "quotation_items.csv");
    document.body.appendChild(link);
    link.click();
}

