        }

        let brands = [...new Set(frm.doc.items.map(item => item.brand).filter(b => b))]; // Get unique brands

        if (brands.length > 0) {
            frappe.call({
                method: "erpnext_mxt.custom_functions.brand_discount.get_brand_discounts",
                args: {
                    brand_list: JSON.stringify(brands)  // Convert list to JSON for Frappe
                },
                callback: function (response) {
                    if (response.message) {
                        let pricing_rules = response.message;
                        let changed_discounts = [];

                        frm.doc.items.forEach(item => {
                            let rule = pricing_rules.find(r => r.brand === item.brand);
                            if (rule && rule.custom_default_discount_percentage !== item.discount_percentage) {
                                changed_discounts.push({
                                    item_code: item.item_code,
                                    brand: item.brand,
                                    old_discount: item.discount_percentage,
                                    new_discount: rule.custom_default_discount_percentage
                                });
                            }
                        });

                        if (changed_discounts.length > 0) {
                            let message = "The following items have updated brand discounts based on Pricing Rules:<br>";
                            changed_discounts.forEach(d => {
                                message += `<br><b>Item:</b> ${d.item_code} | <b>Brand:</b> ${d.brand} | <b>Applied Discount:</b> ${d.old_discount}% → <b>Current Discount:</b> ${d.new_discount}%`;
                            });

                            frappe.msgprint({
                                title: __('Discount Change Alert'),
                                message: message,
                                indicator: 'orange'
                            });

                            // Set flag to prevent repeated pop-ups
                            frm.__discount_alert_shown = true;
                        }
                    }
                }
            });
        }
