                          console.log("Fetching complete, opportunity_owner set.");
                        } else {
                          frappe.msgprint(__('No User ID found for Employee {0}', [sales_person_doc.employee]));
                        }
                      });
                  } else {
                    frappe.msgprint(__('No Employee linked with Sales Person {0}', [sales_person]));
                  }
                });
            } else {
              frappe.msgprint(__('No Sales Person found in Customer Sales Team'));
            }
          } else {
            frappe.msgprint(__('No Sales Team found for this Customer'));
          }
        })
        .catch(error => {
          console.error("Error while fetching customer details:", error);
        });
    }
  }
});

function setup_unsaved_changes_warning(frm) {
    // Ensure no duplicate handlers
    if (frm.unsaved_changes_warning_initialized) return;

    frm.unsaved_changes_warning_initialized = true;

    // Local flags
    frm.unsaved_changes_warning = {
        showing_confirm: false,
        has_left: false
    };

    // Store original handler
    const original_route_handler = function(new_route) {
        console.log(`[${frm.doctype}] Detected route change:`, new_route);

        if (frm.is_dirty() && !frm.unsaved_changes_warning.has_left && !frm.unsaved_changes_warning.showing_confirm) {
            console.log(`[${frm.doctype}] Unsaved changes detected.`);

            frm.unsaved_changes_warning.showing_confirm = true;

            // Cancel the route transition by reverting back
            frappe.set_route("Form", frm.doctype, frm.docname);

            frappe.confirm(
                'You have unsaved changes. Are you sure you want to leave?',
                () => {
                    frm.unsaved_changes_warning.has_left = true;
                    frm.unsaved_changes_warning.showing_confirm = false;
                    console.log(`[${frm.doctype}] User confirmed exit — proceeding.`);
                    frappe.set_route('List', frm.doctype);
                },
                () => {
                    frm.unsaved_changes_warning.showing_confirm = false;
                    console.log(`[${frm.doctype}] User cancelled — staying on form.`);
                }
            );

        } else {
            console.log(`[${frm.doctype}] No warning needed.`);
        }
    };

    // Register handler only once
    frappe.router.on('change', original_route_handler);
}

frappe.ui.form.on('Quotation', {
    refresh: function (frm) {
        setup_unsaved_changes_warning(frm);
    }
});

frappe.ui.form.on('Customer', {
    before_save: function(frm) {
        console.log("Notify Triggered for", frm.doc.name);

        // Check if there is a sales_team child table and if it has entries
        if (frm.doc.sales_team && frm.doc.sales_team.length > 0) {
            frm.doc.sales_team.forEach(row => {
                console.log("Checking Sales Person:", row.sales_person);

                // Fetch employee linked to the sales person
                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Sales Person",
                        filters: { name: row.sales_person },
                        fieldname: "employee"
                    },
                    callback: function(response) {
                        let employee_id = response.message && response.message.employee;
                        console.log("Employee ID:", employee_id);

                        if (employee_id) {
                            // Fetch user_id linked to the employee
                            frappe.call({
                                method: "frappe.client.get_value",
                                args: {
                                    doctype: "Employee",
                                    filters: { name: employee_id },
                                    fieldname: "user_id"
                                },
                                callback: function(emp_response) {
                                    let user_id = emp_response.message && emp_response.message.user_id;
                                    console.log("User ID:", user_id);

                                    if (user_id) {
                                        // Create Notification Log
                                        frappe.call({
                                            method: "frappe.client.insert",
                                            args: {
                                                doc: {
                                                    doctype: "Notification Log",
                                                    for_user: user_id,
                                                    type: "Alert",
                                                    document_type: "Customer",
                                                    document_name: frm.doc.name,
                                                    subject: `<b>${frm.doc.customer_name}</b> Assigned`,
                                                    email_content: `A new customer <b>${frm.doc.customer_name}</b> has been assigned to you.`,
                                                    from_user: frappe.session.user,
                                                }
                                            },
                                            callback: function(log_response) {
                                                console.log("Notification Log created for", user_id, log_response);
                                            }
                                        });
                                    } else {
                                        console.warn(`No user_id found for Employee: ${employee_id}`);
                                    }
                                }
                            });
                        } else {
                            console.warn(`No employee linked to Sales Person: ${row.sales_person}`);
                        }
                    }
                });
            });
        } else {
            console.log("No sales team members assigned.");
        }
    }
});

